import { effect, onCleanup } from '@vorzelajs/core'
import { Show } from '@vorzelajs/dom'
import { accessorOf } from '~/hooks/index.ts'
import { cx } from '~/lib/cx.ts'
import { Portal } from '~/components/primitives/portal.tsx'
import { X } from './icons.tsx'
import styles from './lightbox.module.scss'

export interface LightboxProps {
  open: boolean | (() => boolean)
  src: string
  alt?: string
  onClose: () => void
  caption?: string
  className?: string
}

function LightboxPanel(props: Omit<LightboxProps, 'open'>) {
  effect(() => {
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') props.onClose()
    }
    document.addEventListener('keydown', onKeyDown)
    onCleanup(() => document.removeEventListener('keydown', onKeyDown))
  })

  return (
    <Portal>
      <div
        className={cx(styles.root, props.className)}
        role="dialog"
        aria-modal="true"
        aria-label={props.alt || 'Image preview'}
        onClick={() => props.onClose()}
      >
        <button
          type="button"
          className={styles.close}
          onClick={(event) => {
            event.stopPropagation()
            props.onClose()
          }}
          aria-label="Close"
        >
          <X aria-hidden />
        </button>
        <figure className={styles.figure} onClick={(event) => event.stopPropagation()}>
          <img className={styles.image} src={props.src} alt={props.alt ?? ''} />
          {props.caption ? <figcaption className={styles.caption}>{props.caption}</figcaption> : null}
        </figure>
      </div>
    </Portal>
  )
}

/** Full-screen image viewer. */
export function Lightbox({ open, ...props }: LightboxProps) {
  const isOpen = accessorOf(open)
  return (
    <Show when={isOpen}>
      {() => <LightboxPanel {...props} />}
    </Show>
  )
}

@use 'styles' as vz;

.root {
  position: fixed;
  inset: 0;
  z-index: vz.z('modal');
  display: grid;
  place-items: center;
  padding: vz.space(6);
  background: rgb(0 0 0 / 0.82);
}

.close {
  position: absolute;
  top: vz.space(4);
  right: vz.space(4);
  display: grid;
  place-items: center;
  width: vz.space(10);
  height: vz.space(10);
  border-radius: 50%;
  color: white;
  background: rgb(255 255 255 / 0.12);

  svg {
    width: 20px;
    height: 20px;
  }
}

.figure {
  max-width: min(92vw, 80rem);
  max-height: 88vh;
  margin: 0;
}

.image {
  max-width: 100%;
  max-height: 82vh;
  border-radius: vz.radius('lg');
  object-fit: contain;
}

.caption {
  margin-top: vz.space(3);
  color: rgb(255 255 255 / 0.78);
  font-size: vz.font-size('sm');
  text-align: center;
}
